import {sectors} from './core.mjs';
export function drawBoard(canvas,darts=[]){const ctx=canvas.getContext('2d'),s=canvas.width,c=s/2,R=s*.485;ctx.clearRect(0,0,s,s);ctx.save();ctx.translate(c,c);ctx.beginPath();ctx.arc(0,0,R,0,Math.PI*2);ctx.fillStyle='#05060a';ctx.fill();ctx.strokeStyle='#ff8591';ctx.lineWidth=5;ctx.stroke();const outer=R*.775;for(let i=0;i<20;i++){let a=-Math.PI/2-Math.PI/20+i*Math.PI/10,b=a+Math.PI/10;ring(0,outer,a,b,i%2?'#e6d2be':'#05060b');ring(outer*162/170,outer,a,b,i%2?'#159c70':'#df244d');ring(outer*99/170,outer*107/170,a,b,i%2?'#159c70':'#df244d');ctx.strokeStyle='#8b9b9899';ctx.lineWidth=.8;ctx.beginPath();ctx.moveTo(0,0);ctx.lineTo(Math.cos(a)*outer,Math.sin(a)*outer);ctx.stroke();ctx.fillStyle='#899092';ctx.font=`700 ${s*.031}px system-ui`;ctx.textAlign='center';ctx.textBaseline='middle';let angle=-Math.PI/2+i*Math.PI/10;ctx.save();ctx.translate(Math.cos(angle)*R*.944,Math.sin(angle)*R*.944);ctx.fillText(sectors[i],0,0);ctx.restore();}for(let rad of [outer,outer*162/170,outer*99/170,outer*107/170]){ctx.beginPath();ctx.arc(0,0,rad,0,7);ctx.strokeStyle='#8b9b9899';ctx.lineWidth=.8;ctx.stroke();}ctx.beginPath();ctx.arc(0,0,outer*15.9/170,0,7);ctx.fillStyle='#159c70';ctx.fill();ctx.stroke();ctx.beginPath();ctx.arc(0,0,outer*6.35/170,0,7);ctx.fillStyle='#df244d';ctx.fill();ctx.stroke();ctx.textAlign='center';ctx.fillStyle='#e6d2be';ctx.font=`900 ${s*.044}px system-ui`;ctx.fillText('WINMAU',0,-R*.845);ctx.font=`600 ${s*.018}px system-ui`;ctx.letterSpacing='3px';ctx.fillStyle='#8d9ab1';ctx.fillText('LIVE DARTS',0,R*.845);ctx.letterSpacing='0px';darts.forEach((d,i)=>{if(!Number.isFinite(d.bx))return;let x=d.bx*outer,y=d.by*outer;ctx.beginPath();ctx.arc(x,y,10,0,7);ctx.fillStyle=d.source==='camera'?'#2777ff':'#fff';ctx.fill();ctx.strokeStyle='#fff';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#fff';ctx.font=`800 ${s*.024}px system-ui`;ctx.fillText(i+1,x+18,y-15);});ctx.restore();function ring(inner,outer,a,b,color){ctx.beginPath();ctx.arc(0,0,outer,a,b);ctx.arc(0,0,inner,b,a,true);ctx.closePath();ctx.fillStyle=color;ctx.fill();}}
export function boardPoint(canvas,clientX,clientY){const rect=canvas.getBoundingClientRect(),outer=canvas.width*.485*.775;return {x:((clientX-rect.left)*canvas.width/rect.width-canvas.width/2)/outer,y:((clientY-rect.top)*canvas.height/rect.height-canvas.height/2)/outer};}
